/** 四相 —— 这是真相。渲染端应当消费这个，而不是三态投影。 */
export type RenderPhase = "formless" | "liminal" | "manifest" | "receding";

/** 三态公共投影。仅供必须使用公共词汇的消费者；用它画图会丢掉返回弧。 */
